-- Seed: shared catalog of 40 reading texts (levels 1-8, five each). institution_id NULL = every institution sees them.
-- Requires 004. Re-runnable: same (source, source_id) is skipped; to correct a text, edit it here and use DO UPDATE.
INSERT INTO reading_texts (institution_id, source, source_id, title, level, content, word_count)
SELECT NULL, 'catalogo', v.source_id, v.title, v.level, v.content, v.word_count
FROM (VALUES
  (1, 'La caja de Lola', 1::smallint, 'Lola tiene una caja roja. La caja está bajo su cama. Un día, Lola la abre y mira lo que hay. Ve una foto, una cinta y un oso de tela. Lola toma el oso y lo pone junto a su almohada. Luego guarda la caja.', 46),
  (2, 'El gato de Tomás', 1::smallint, 'Tomás mira por la ventana. Su gato Tito está en el patio, cerca de una flor. Tito salta sobre una hoja y corre al árbol. Tomás abre la puerta y lo llama. El gato viene con pasos lentos. Al fin, los dos entran a la casa.', 46),
  (3, 'Un día de lluvia', 1::smallint, 'Hoy cae mucha lluvia. Ana mira las gotas en el vidrio. Su mamá le da una taza de leche tibia. Ana se sienta junto a la mesa y dibuja una nube. Cuando sale el sol, mira el patio. Una pequeña ave canta sobre el muro.', 45),
  (4, 'La semilla', 1::smallint, 'Una semilla es muy pequeña. Puede estar dentro de una fruta o en una flor. Si tiene agua, aire y un buen lugar, puede crecer. Primero sale una raíz. Luego nace un tallo con hojas. Con el tiempo, la planta se hace más grande.', 44),
  (5, 'El pan de la abuela', 1::smallint, 'La abuela hace pan en casa. Pone harina en un bol y le agrega agua. Luego mueve la masa con sus manos. Pedro mira todo con mucha atención. Más tarde, el pan sale del horno. La abuela corta un trozo y lo deja enfriar.', 44),
  (6, 'La visita al huerto', 2::smallint, 'El curso de Camila visitó un huerto cerca del colegio. Allí vieron lechugas, tomates y muchas flores. La señora Julia les mostró cómo cuidar la tierra sin dañar las plantas. Cada niño puso una semilla en una maceta pequeña. Antes de volver a clases, todos prometieron regar sus semillas y mirar cómo cambiaban durante las semanas siguientes.', 57),
  (7, 'La bicicleta azul', 2::smallint, 'Martín recibió una bicicleta azul para su cumpleaños. Al principio, le daba miedo pedalear sin ayuda. Su hermana lo acompañó hasta una plaza tranquila y le enseñó a mirar hacia adelante. Martín practicó muchas veces y algunas veces perdió el equilibrio. Después de varios intentos, pudo avanzar solo. Esa tarde volvió feliz a casa y guardó su casco con mucho cuidado.', 61),
  (8, '¿Por qué cantan las aves?', 2::smallint, 'Algunas aves cantan para comunicarse con otras de su especie. Sus sonidos pueden servir para llamar a sus parejas o avisar que un lugar está ocupado. No todas las aves cantan de la misma manera. Algunas producen silbidos cortos y otras repiten melodías largas. Si escuchamos con atención en una plaza, podemos reconocer varios cantos diferentes durante una misma mañana.', 60),
  (9, 'Una sorpresa en la biblioteca', 2::smallint, 'El lunes, Sofía fue a la biblioteca de su escuela para buscar un libro de animales. Mientras revisaba los estantes, encontró una tarjeta con un dibujo de una estrella. La bibliotecaria le explicó que era una invitación a un juego de pistas. Sofía siguió las instrucciones y descubrió una mesa llena de cuentos nuevos. Eligió uno y comenzó a leerlo allí mismo.', 62),
  (10, 'El agua en casa', 2::smallint, 'Usamos agua para beber, cocinar, lavar y cuidar las plantas. Aunque parece que siempre sale de la llave, no debemos desperdiciarla. Podemos cerrar la llave mientras nos cepillamos los dientes y avisar cuando una tubería gotea. También es útil juntar agua de lluvia para regar, cuando es seguro hacerlo. Pequeñas acciones diarias ayudan a cuidar este recurso importante.', 58),
  (11, 'El mapa del parque', 3::smallint, 'Isidora y Benjamín encontraron un mapa durante una visita al parque. En el papel aparecían los senderos, un puente y una zona de árboles nativos. Decidieron seguir la ruta marcada con círculos verdes. Primero pasaron por un jardín de flores y luego escucharon el sonido de un estero. Cuando llegaron al puente, observaron varias piedras cubiertas de musgo. Al regresar, explicaron a su profesora cómo habían usado los símbolos del mapa para orientarse sin perderse.', 75),
  (12, 'Las abejas y las flores', 3::smallint, 'Las abejas visitan las flores para recoger néctar y polen. Mientras se mueven de una flor a otra, pueden transportar parte del polen y favorecer la reproducción de muchas plantas. Este proceso se llama polinización. Las abejas no trabajan solas: viven en colonias donde cumplen tareas diferentes. Algunas buscan alimento y otras cuidan la colmena. Para ayudarlas, es importante proteger las flores y evitar dañar los lugares donde viven. Observarlas desde una distancia tranquila permite conocer mejor su trabajo.', 79),
  (13, 'El ensayo de música', 3::smallint, 'El curso preparaba una presentación musical para celebrar el aniversario del colegio. Elisa tocaba un tambor pequeño y Diego estaba a cargo de las maracas. Durante el primer ensayo, algunos estudiantes comenzaron antes de tiempo y la canción sonó desordenada. La profesora pidió que escucharan el ritmo y esperaran una señal. Al segundo intento, todos lograron tocar juntos. Comprendieron que una presentación no depende solo de practicar cada instrumento, sino también de prestar atención a los demás.', 77),
  (14, 'Una mochila más liviana', 3::smallint, 'Cada mañana llevamos materiales diferentes en la mochila. Si guardamos objetos que no necesitamos, aumenta el peso que debemos cargar. Una buena idea es revisar el horario antes de salir de casa. También conviene colocar los libros más pesados cerca de la espalda y usar las dos correas. Así, la mochila queda mejor equilibrada. Prepararla la noche anterior permite encontrar con calma los cuadernos y evitar olvidos. Una rutina sencilla puede hacer más cómodo el camino a la escuela.', 79),
  (15, 'El mensaje en la botella', 3::smallint, 'Durante una caminata por la playa, Emilia encontró una botella vacía junto a unas rocas. En su interior había un papel doblado. Al abrirlo, descubrió un dibujo de un faro y una pregunta: ¿Qué hace especial a este lugar? Emilia pensó en las aves, el sonido de las olas y las familias que paseaban por la arena. Escribió su respuesta en una libreta y guardó el papel para mostrarlo en clases. Después recogió la botella y la llevó al punto de reciclaje.', 82),
  (16, 'La sombra del reloj solar', 4::smallint, 'Mucho antes de que existieran los relojes digitales, algunas personas observaban la sombra de un objeto para calcular el paso de las horas. Un reloj solar utiliza la posición del Sol y la sombra que proyecta una pieza fija sobre una superficie marcada. Durante el día, la sombra cambia de lugar porque la Tierra gira. Sin embargo, este instrumento no funciona de la misma forma durante la noche ni cuando no llega luz solar directa. En una actividad de ciencias, un curso puede registrar la sombra de una vara a distintas horas y comparar los resultados. Así descubre que medir el tiempo también requiere observar patrones de la naturaleza.', 109),
  (17, 'La competencia de cometas', 4::smallint, 'En una feria de ciencias, varios equipos construyeron cometas con papel, varillas y cuerda. El grupo de Vicente eligió una cometa amarilla con una cola muy larga. Cuando llegó el momento de probarla, el viento la movió de lado y casi cayó al suelo. En vez de rendirse, el equipo revisó cómo estaban unidas las piezas y acortó la cola. Al segundo intento, la cometa se elevó con estabilidad. No ganaron el premio a la mayor altura, pero recibieron un reconocimiento por explicar cada cambio que hicieron. Aprendieron que probar una idea y corregirla puede ser tan importante como obtener un resultado.', 102),
  (18, 'Un bosque después de la lluvia', 4::smallint, 'Después de una lluvia intensa, el bosque presenta sonidos y colores distintos. Las hojas conservan pequeñas gotas que reflejan la luz, mientras el suelo húmedo desprende un olor característico. Algunos insectos se esconden bajo troncos y piedras; otros vuelven a moverse cuando mejora el tiempo. Los hongos pueden aparecer en zonas donde existe humedad suficiente y materia orgánica. Durante una salida pedagógica, es importante caminar por senderos habilitados, observar sin arrancar plantas y evitar dejar basura. Un bosque es un ambiente donde muchos seres vivos dependen unos de otros. Mirarlo con atención ayuda a comprender por qué es necesario protegerlo.', 100),
  (19, 'La radio escolar', 4::smallint, 'Un grupo de cuarto básico decidió crear un programa de radio para compartir noticias del colegio. Martina escribió las preguntas, José preparó una breve sección de deportes y Fernanda revisó el pronóstico del tiempo. En la primera grabación hablaron al mismo tiempo y costaba entender sus ideas. Entonces organizaron turnos y practicaron la pronunciación de los nombres. La siguiente grabación resultó mucho más clara. Cuando escucharon el programa terminado, descubrieron que comunicar una noticia exige seleccionar información confiable, escuchar a los compañeros y hablar con un volumen adecuado. Después invitaron a otros cursos a proponer temas para futuras emisiones.', 99),
  (20, 'El viaje de una gota', 4::smallint, 'El agua de ríos, lagos y océanos puede pasar al aire cuando recibe energía del Sol. Este cambio se llama evaporación. Más arriba, el vapor se enfría y forma pequeñas gotas que pueden reunirse en las nubes. Cuando las gotas crecen lo suficiente, caen como lluvia. Una parte del agua se filtra en el suelo y otra vuelve a los ríos. Este recorrido es conocido como ciclo del agua. Aunque sus etapas se suelen representar con flechas, en la naturaleza ocurren de manera continua. Comprender este proceso nos ayuda a explicar algunos cambios del tiempo y la importancia de cuidar las fuentes de agua dulce.', 105),
  (21, 'La expedición al humedal', 5::smallint, 'La escuela organizó una salida a un humedal cercano para estudiar la biodiversidad. Antes de comenzar, la profesora recordó que era importante caminar en silencio y mantenerse en el sendero. Un grupo observó aves de patas largas que buscaban alimento en el agua poco profunda. Otro registró plantas capaces de crecer en suelos muy húmedos. Durante el recorrido, Catalina encontró una bolsa plástica atrapada entre los juncos. Avisó al guía, quien la retiró de manera segura. Al terminar, cada equipo comparó sus registros y descubrió que el humedal sirve de refugio para numerosos seres vivos. También comprendieron que la basura puede alterar ese equilibrio. En clases prepararon una campaña con recomendaciones para visitar estos espacios sin dañarlos.', 117),
  (22, 'El secreto de las semillas viajeras', 5::smallint, 'Las plantas no pueden caminar para buscar nuevos lugares donde crecer, pero muchas producen semillas capaces de desplazarse. Algunas tienen estructuras livianas que el viento transporta a gran distancia. Otras flotan en el agua y llegan hasta nuevas orillas. También existen frutos que se adhieren al pelaje de ciertos animales o que son comidos por ellos. Cuando las semillas se depositan en un sitio adecuado, pueden germinar si reciben las condiciones necesarias. Este fenómeno, llamado dispersión, ayuda a que las plantas ocupen distintos ambientes. Sin embargo, no todas las semillas llegan a desarrollarse: algunas caen sobre superficies secas o son consumidas. Observar la forma de los frutos permite formular hipótesis sobre cómo viajan sus semillas.', 115),
  (23, 'El desafío de los puentes', 5::smallint, 'En tecnología, la profesora propuso diseñar un puente pequeño con materiales reutilizables. Cada equipo debía explicar cómo distribuiría el peso y comprobar si su estructura era estable. El grupo de Antonia construyó primero una base larga y delgada que se dobló al colocar varios libros. En lugar de comenzar desde cero, analizaron dónde se había producido el problema. Añadieron soportes triangulares y reforzaron las uniones con cinta. La segunda versión resistió una carga mayor. Cuando presentaron sus resultados, mostraron fotografías de ambos modelos y explicaron por qué habían cambiado el diseño. La experiencia les enseñó que una solución técnica necesita pruebas, evidencia y disposición para modificar las primeras ideas.', 109),
  (24, 'El lenguaje de los mapas', 5::smallint, 'Un mapa representa información sobre un territorio mediante símbolos, líneas y colores. La escala permite relacionar las distancias dibujadas con las distancias reales, mientras que la leyenda explica el significado de cada símbolo. También es útil reconocer los puntos cardinales para orientar una ruta. Los mapas pueden mostrar información física, como montañas y ríos, o aspectos humanos, como caminos y ciudades. Actualmente existen mapas digitales que permiten ampliar zonas y consultar distintos recorridos. Sin embargo, ningún mapa contiene todos los detalles del lugar que representa. Por eso es importante revisar su propósito y la fecha en que fue elaborado. Interpretar mapas ayuda a planificar trayectos y comprender cómo se organiza un espacio.', 112),
  (25, 'La feria de intercambio', 5::smallint, 'En el colegio de Matías organizaron una feria para intercambiar libros que ya habían leído. La idea era darles una segunda oportunidad y compartir recomendaciones entre estudiantes. Cada participante escribió una ficha con el título de su libro y una breve explicación de por qué lo recomendaba. Al principio, Matías pensó que nadie elegiría su novela de aventuras porque tenía la portada algo gastada. Sin embargo, una compañera se interesó al escuchar su descripción de la historia. Ella le ofreció a cambio un libro de misterios. Al finalizar la jornada, ambos se fueron con una lectura diferente. La actividad demostró que el valor de un libro no depende solamente de su apariencia, sino de las experiencias que puede despertar.', 119),
  (26, 'El agua escondida bajo nuestros pies', 6::smallint, 'Cuando pensamos en reservas de agua, solemos imaginar ríos, lagos y embalses. Sin embargo, parte del agua de lluvia se infiltra en el terreno y puede acumularse entre los espacios de ciertas rocas y sedimentos. Esta agua subterránea alimenta pozos y, en algunos lugares, también contribuye al caudal de manantiales y cursos de agua. Su disponibilidad depende del clima, la geología y la cantidad que se extrae. Si un acuífero recibe menos agua de la que pierde durante mucho tiempo, su nivel puede disminuir. Por eso resulta importante utilizar el recurso de manera responsable y proteger las zonas donde se produce la recarga. Comprender lo que ocurre bajo la superficie permite tomar mejores decisiones sobre el cuidado del agua.', 119),
  (27, 'La entrevista inesperada', 6::smallint, 'El taller de periodismo escolar preparaba entrevistas a personas que aportaban a la comunidad. A Valentina le correspondió conversar con un vecino que reparaba bicicletas de manera voluntaria. Había escrito diez preguntas, pero cuando comenzó la conversación descubrió que algunas respuestas eran mucho más interesantes de lo previsto. En vez de seguir rígidamente su lista, escuchó con atención y formuló nuevas preguntas. El vecino contó que había aprendido el oficio observando a su abuelo y que ahora enseñaba a otros jóvenes. Después, Valentina revisó sus notas para distinguir los hechos de sus propias opiniones. Al publicar la entrevista, comprendió que investigar exige preparación, pero también curiosidad y respeto por la voz de quien comparte su experiencia.', 116),
  (28, 'La ciudad que escucha al río', 6::smallint, 'Los ríos que atraviesan ciudades pueden cumplir funciones ambientales y sociales muy importantes. Sus riberas ofrecen espacios para distintas especies y, cuando están bien cuidadas, también pueden convertirse en lugares de encuentro para las personas. Sin embargo, construir demasiado cerca del cauce o arrojar residuos puede alterar el funcionamiento natural del río. Durante lluvias intensas, el agua necesita espacios por donde desplazarse. Por eso, los proyectos urbanos deben considerar información sobre inundaciones, vegetación y características del terreno. En varias comunidades, estudiantes y organizaciones vecinales participan en campañas de limpieza y observación del entorno. Estas acciones no reemplazan las decisiones de las autoridades, pero ayudan a comprender que el bienestar de una ciudad depende también de sus ecosistemas.', 117),
  (29, 'Una señal desde el observatorio', 6::smallint, 'Durante una visita a un observatorio, un grupo de estudiantes aprendió por qué el norte de Chile ofrece condiciones favorables para observar el cielo. La guía explicó que la atmósfera, la iluminación de las ciudades y el clima pueden afectar la nitidez de las imágenes. Luego les mostró cómo los astrónomos comparan observaciones realizadas en distintos momentos. Ignacio esperaba ver planetas enormes directamente por el telescopio, pero descubrió que muchas imágenes necesitan instrumentos y procesamiento de datos. Al principio se sintió decepcionado; después comprendió que la ciencia no consiste solo en mirar, sino en interpretar evidencias. Al regresar a la escuela, preparó una exposición para explicar por qué una imagen científica puede contener información que nuestros ojos no distinguen.', 119),
  (30, 'El debate del recreo', 6::smallint, 'El centro de estudiantes propuso instalar más zonas con sombra en el patio. Algunos cursos querían plantar árboles, mientras otros preferían estructuras que pudieran utilizarse de inmediato. Durante una reunión, las opiniones comenzaron a repetirse sin que nadie escuchara las razones del grupo contrario. La presidenta propuso organizar un debate con turnos de palabra y antecedentes verificables. Un equipo investigó el tiempo que tardan distintas especies en crecer y otro consultó sobre costos de mantención. Finalmente, acordaron presentar una propuesta que combinara soluciones de corto y largo plazo. Aunque no todos obtuvieron exactamente lo que querían, aprendieron que una decisión colectiva mejora cuando se consideran las necesidades, las evidencias y las consecuencias de cada alternativa.', 115),
  (31, 'La memoria de los glaciares', 7::smallint, 'Los glaciares son grandes masas de hielo que se forman cuando la nieve acumulada durante muchos años se comprime. Aunque parecen inmóviles, se desplazan lentamente debido a su propio peso. Los científicos estudian su extensión y espesor para comprender cómo cambian las condiciones ambientales. En ciertas zonas, el hielo conserva capas que permiten obtener pistas sobre el clima del pasado. Hoy, numerosos glaciares del planeta están perdiendo masa, fenómeno que tiene consecuencias para los ecosistemas y las reservas de agua. Sin embargo, el comportamiento de cada glaciar depende de factores locales, como la altitud, las precipitaciones y la temperatura. Por eso, los investigadores combinan imágenes satelitales, mediciones en terreno y registros históricos. Comprender estos cambios no significa predecir exactamente el futuro de cada valle, sino disponer de información útil para proteger las fuentes de agua y planificar responsablemente.', 138),
  (32, 'La fotografía que faltaba', 7::smallint, 'Para una exposición sobre la historia del barrio, el curso reunió fotografías familiares y testimonios de vecinos mayores. Antonia encontró una imagen sin fecha donde aparecía una plaza que ya no existía. Al principio pensó que bastaba con publicarla junto a una descripción inventada, pero su compañero le recordó que debían comprobar la información. Visitaron la biblioteca comunal y compararon la fotografía con planos antiguos. Después entrevistaron a una vecina que recordó cuándo se construyeron los edificios de ese sector. Descubrieron que la imagen era más antigua de lo que suponían. En el panel final incluyeron la fecha aproximada y explicaron cómo habían llegado a esa conclusión. El trabajo les permitió distinguir entre recuerdos personales, interpretaciones y datos confirmados. También comprendieron que conservar la memoria de un lugar exige escuchar distintas voces y reconocer aquello que todavía se desconoce.', 139),
  (33, 'El costo invisible de la ropa', 7::smallint, 'Cuando elegimos una prenda de vestir, solemos fijarnos en su precio, color o comodidad. Sin embargo, producir ropa también requiere materias primas, energía, agua y transporte. Los impactos ambientales varían según el tipo de fibra, los procesos utilizados y la vida útil de cada producto. Por eso no basta con afirmar que un material es siempre mejor que otro. Conviene analizar todo el recorrido de la prenda, desde su fabricación hasta el momento en que deja de utilizarse. Reparar una costura, intercambiar ropa en buen estado o comprar solo lo necesario son acciones que pueden prolongar su uso. Al mismo tiempo, las empresas y autoridades tienen responsabilidades sobre la información que entregan y las condiciones de producción. Comprender estos factores permite tomar decisiones de consumo más informadas, sin reducir un problema complejo a una sola solución.', 136),
  (34, 'Una solución para el patio', 7::smallint, 'Después de varias semanas de lluvia, una zona del patio escolar quedaba cubierta de agua. Los estudiantes de séptimo propusieron resolver el problema mediante un proyecto de investigación. Primero observaron dónde se acumulaba el agua y registraron cuánto tardaba en desaparecer. Luego compararon distintas superficies y descubrieron que algunas permitían una mayor infiltración. Un grupo quería cubrir todo el sector con cemento, pero otro señaló que esa medida podría aumentar el escurrimiento hacia zonas cercanas. En vez de elegir la idea más rápida, prepararon modelos pequeños y consultaron a personal especializado del establecimiento. Su propuesta final incluyó mejorar el drenaje y conservar un espacio con vegetación. El proyecto todavía necesitaba evaluación técnica, pero permitió al curso comprender que una intervención debe considerar tanto su eficacia inmediata como sus efectos sobre el entorno.', 132),
  (35, 'Cómo cambia una noticia', 7::smallint, 'Una noticia puede circular rápidamente por redes sociales, conversaciones y medios de comunicación. Durante ese recorrido, algunas personas comparten solo el título, otras agregan opiniones y otras publican imágenes sin explicar su contexto. Así, un hecho puede terminar presentado de maneras muy diferentes. Para interpretar una noticia conviene identificar quién la publicó, cuándo ocurrió el acontecimiento y qué fuentes respaldan la información. También es importante distinguir una afirmación comprobable de una opinión. Cuando dos medios entregan versiones distintas, comparar las evidencias puede ser más útil que elegir de inmediato el mensaje que confirma nuestras ideas. La lectura crítica exige tiempo y atención, pero ayuda a evitar conclusiones precipitadas. Antes de compartir una publicación, una pregunta sencilla puede marcar la diferencia: ¿sé realmente de dónde proviene lo que estoy leyendo?', 129),
  (36, 'La ciencia de las decisiones pequeñas', 8::smallint, 'En la vida cotidiana tomamos numerosas decisiones que parecen insignificantes: elegir una ruta, organizar el tiempo o decidir qué información compartir. Sin embargo, cuando una acción se repite, sus efectos pueden acumularse. Esto ocurre, por ejemplo, con el consumo de energía en una comunidad escolar. Apagar luces en espacios desocupados puede ayudar, pero la magnitud del ahorro depende también del tipo de iluminación, los horarios y las condiciones del edificio. Por eso, una campaña responsable no debería basarse únicamente en buenas intenciones. Es posible comenzar registrando datos, establecer una comparación antes y después de las medidas y revisar si aparecieron factores que alteraron los resultados. Un cambio observable no demuestra por sí solo una relación de causa y efecto. Aprender a evaluar nuestras decisiones mediante evidencia permite reconocer avances reales, corregir errores y proponer mejoras que puedan mantenerse en el tiempo.', 141),
  (37, 'La discusión sobre el archivo', 8::smallint, 'El consejo escolar recibió una propuesta para digitalizar fotografías y documentos antiguos del establecimiento. La idea entusiasmó a varios estudiantes, quienes imaginaban una página donde cualquier persona pudiera explorar la historia del colegio. Sin embargo, durante la primera reunión surgieron preguntas que nadie había considerado: ¿quién autorizaría la publicación de imágenes personales?, ¿cómo se verificarían las fechas?, ¿qué ocurriría con los archivos deteriorados? En lugar de abandonar el proyecto, el equipo decidió establecer criterios. Consultaron a docentes, organizaron un inventario y separaron los materiales que requerían permisos adicionales. También acordaron guardar copias de respaldo y registrar el origen de cada documento. Aunque el trabajo avanzó más lentamente de lo previsto, el resultado fue una colección pequeña y ordenada. Comprendieron que preservar la memoria de una comunidad implica tanto facilitar el acceso como respetar a las personas vinculadas con esa historia.', 140),
  (38, '¿Puede una ciudad ser más fresca?', 8::smallint, 'Durante el verano, algunas calles presentan temperaturas más elevadas que parques y zonas con vegetación. Este fenómeno se relaciona, entre otros factores, con materiales que absorben y liberan calor, la presencia de edificios y la escasez de sombra. Los árboles pueden contribuir a moderar las condiciones locales mediante la sombra y la evaporación del agua, aunque su efecto depende de la especie y del espacio disponible. Para estudiar estas diferencias, un grupo de investigadores podría comparar mediciones tomadas a la misma hora en lugares con características distintas. También tendría que considerar el viento, la humedad y los instrumentos empleados. A partir de esos datos sería posible proponer mejoras, como proteger áreas verdes o elegir superficies adecuadas para determinados espacios. Sin embargo, ninguna intervención resulta idéntica en todas las ciudades: planificar exige comprender las necesidades de cada comunidad y evaluar sus resultados.', 141),
  (39, 'Una conclusión apresurada', 8::smallint, 'En una feria científica, Daniela presentó un experimento sobre el crecimiento de plantas bajo distintas condiciones de iluminación. Había observado que una de sus macetas creció más que las demás y concluyó que la luz utilizada era la mejor posible. Durante las preguntas, un compañero señaló que las plantas también habían recibido cantidades diferentes de agua. Daniela comprendió entonces que su conclusión podía ser incorrecta: había cambiado más de una variable al mismo tiempo. Aunque se sintió frustrada, registró la observación y decidió repetir el ensayo con condiciones controladas. En la nueva versión mantuvo iguales el tipo de tierra, la cantidad de agua y el tamaño de las macetas. Los resultados fueron menos llamativos, pero permitieron una comparación más clara. Al terminar la feria, explicó que reconocer una limitación metodológica no invalida todo el esfuerzo; al contrario, puede ser el primer paso para construir conocimiento más confiable.', 147),
  (40, 'El valor de una pregunta', 8::smallint, 'En una conversación grupal, hacer una pregunta puede ser más útil que entregar una respuesta inmediata. Las preguntas permiten reconocer aquello que no comprendemos, comparar explicaciones y examinar los supuestos que sostienen una opinión. Sin embargo, no todas cumplen la misma función. Algunas buscan precisar datos, mientras otras invitan a imaginar consecuencias o a considerar perspectivas diferentes. En el aula, una pregunta bien formulada puede transformar una discusión basada en preferencias personales en una investigación compartida. Para lograrlo, es necesario escuchar la respuesta y estar dispuesto a revisar la propia idea. Esto no significa renunciar a las convicciones, sino distinguir entre lo que sabemos, lo que suponemos y lo que aún necesitamos averiguar. En una época de mensajes rápidos y afirmaciones categóricas, aprender a preguntar con claridad constituye una herramienta valiosa para participar de manera informada y respetuosa en la vida colectiva.', 142)
) AS v(source_id, title, level, content, word_count)
ON CONFLICT (source, source_id) WHERE institution_id IS NULL AND source IS NOT NULL DO NOTHING;
